import { Slot } from "@radix-ui/react-slot";
import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";
import * as React from "react";

import { SpinnerIcon } from "@/components/odia/odia-icons";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  [
    "relative inline-flex shrink-0 items-center justify-center overflow-hidden whitespace-nowrap rounded-full font-medium tracking-[-0.01em] cursor-pointer",
    "transition-all outline-none select-none",
    "focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50",
    "disabled:pointer-events-none disabled:opacity-50 data-[loading=true]:pointer-events-none",
  ],
  {
    defaultVariants: { size: "default", variant: "default" },
    variants: {
      size: {
        default: "h-10 px-5 text-sm",
        icon: "size-10",
        "icon-full": "size-10 rounded-full",
        "icon-sm": "size-8",
        lg: "h-12 px-8 text-base",
        sm: "h-8 gap-1.5 px-3 text-xs",
      },
      variant: {
        // Glossy primary pill — the signature default
        default:
          "border-0 text-primary-foreground " +
          "bg-[linear-gradient(180deg,color-mix(in_oklab,var(--primary)_76%,white)_0%,var(--primary)_100%)] " +
          "shadow-[0_6px_14px_rgba(0,0,0,0.22),inset_0_1px_0_rgba(255,255,255,0.18)] " +
          "hover:brightness-110 hover:shadow-[0_8px_18px_rgba(0,0,0,0.26),inset_0_1px_0_rgba(255,255,255,0.2)] " +
          "active:scale-[0.97] active:brightness-95",
        destructive:
          "border-0 bg-destructive text-white shadow-[0_1px_2px_rgba(0,0,0,0.05),0_4px_12px_rgba(0,0,0,0.10)] hover:bg-destructive/90 active:scale-[0.97] focus-visible:ring-destructive/30",
        // odiaui additions
        frame:
          "border border-primary bg-primary text-primary-foreground " +
          "shadow-[inset_0_0_0_2px_var(--primary),inset_0_0_0_3px_color-mix(in_oklab,var(--primary-foreground)_45%,transparent),0_4px_12px_rgba(0,0,0,0.10)] " +
          "hover:brightness-105 active:brightness-95",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-foreground underline underline-offset-4 decoration-1 hover:decoration-2",
        // Clean white card button
        outline:
          "border bg-card text-foreground " +
          "shadow-[0_1px_2px_rgba(0,0,0,0.04),0_4px_12px_rgba(0,0,0,0.06)] " +
          "hover:bg-accent active:scale-[0.97] dark:bg-muted dark:hover:bg-accent",
        // Quiet neutral pill
        secondary:
          "border-0 bg-muted text-foreground " +
          "shadow-[0_1px_2px_rgba(0,0,0,0.04)] " +
          "hover:bg-accent active:scale-[0.97] dark:hover:bg-accent/70",
      },
    },
  }
);

const iconSize: Record<string, string> = {
  default: "[&>svg]:size-4",
  icon: "[&>svg]:size-5",
  "icon-full": "[&>svg]:size-5",
  "icon-sm": "[&>svg]:size-4",
  lg: "[&>svg]:size-[18px]",
  sm: "[&>svg]:size-3.5",
};

type ButtonProps = React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
    loading?: boolean;
  };

const Button = ({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  loading = false,
  children,
  onClick,
  ...props
}: ButtonProps) => {
  const classes = cn(buttonVariants({ size, variant }), className);

  if (asChild) {
    return (
      <Slot
        data-slot="button"
        className={classes}
        {...(props as React.ComponentProps<typeof Slot>)}
      >
        {children}
      </Slot>
    );
  }

  return (
    <button
      data-slot="button"
      data-loading={loading}
      aria-busy={loading || undefined}
      className={classes}
      onClick={loading ? undefined : onClick}
      {...props}
    >
      <span
        className={cn(
          "relative z-10 inline-flex items-center gap-2 [&>svg]:shrink-0",
          iconSize[size ?? "default"]
        )}
      >
        {loading && <SpinnerIcon className="animate-spin" />}
        {children}
      </span>
    </button>
  );
};

export { Button, buttonVariants };

import * as React from "react";

type IconProps = React.SVGProps<SVGSVGElement>;

const icon = (p: IconProps): IconProps => ({
  "aria-hidden": true,
  fill: "none",
  stroke: "currentColor",
  strokeLinecap: "round",
  strokeLinejoin: "round",
  strokeWidth: 1.75,
  viewBox: "0 0 24 24",
  ...p,
});

const SPOKES = Array.from({ length: 8 }, (_, i) => i * 45);

/* ── Odia icon set ─────────────────────────────────────── */

export const ChakraIcon = (props: IconProps) => (
  <svg {...icon(props)}>
    <circle cx="12" cy="12" r="9.5" />
    <circle cx="12" cy="12" r="2.4" />
    {SPOKES.map((a) => (
      <line
        key={a}
        x1="12"
        y1="9.6"
        x2="12"
        y2="2.5"
        transform={`rotate(${a} 12 12)`}
      />
    ))}
  </svg>
);

export const DeulaIcon = (props: IconProps) => (
  <svg {...icon(props)}>
    <circle cx="12" cy="2.6" r="0.9" />
    <path d="M12 3.5V5.2" />
    <path d="M7 21C7 14 8.6 8.6 12 5.2C15.4 8.6 17 14 17 21" />
    <path d="M8.2 13.5H15.8M9 9.5H15" />
    <path d="M10 21V18.2a2 2 0 0 1 4 0V21" />
    <path d="M4 21H20" />
  </svg>
);
export const TempleIcon = DeulaIcon;

export const PadmaIcon = (props: IconProps) => (
  <svg {...icon(props)}>
    <path d="M12 3.5C14.6 6.5 14.6 10.5 12 14C9.4 10.5 9.4 6.5 12 3.5Z" />
    <path d="M12 14C9 14 6.2 12.2 5.2 8.4C8.6 8.4 11 10.4 12 14Z" />
    <path d="M12 14C15 14 17.8 12.2 18.8 8.4C15.4 8.4 13 10.4 12 14Z" />
    <path d="M12 14C8 15.2 4.2 13.8 2.6 10.6" />
    <path d="M12 14C16 15.2 19.8 13.8 21.4 10.6" />
    <path d="M12 14V20M7 20.5H17" />
  </svg>
);

export const BanaIcon = (props: IconProps) => (
  <svg {...icon(props)}>
    <path d="M6 3V21" />
    <path d="M6 4H17.5L14.2 8L17.5 12H6" />
  </svg>
);

export const ArrowRightIcon = (props: IconProps) => (
  <svg {...icon(props)}>
    <path d="M5 12H19M13 6L19 12L13 18" />
  </svg>
);

export const TrashIcon = (props: IconProps) => (
  <svg {...icon(props)}>
    <path d="M3.5 6H20.5M9 6V4.2C9 3.5 9.5 3 10.2 3H13.8C14.5 3 15 3.5 15 4.2V6" />
    <path d="M5.5 6L6.4 19.6C6.5 20.4 7.1 21 7.9 21H16.1C16.9 21 17.5 20.4 17.6 19.6L18.5 6" />
    <path d="M10 10.5V16.5M14 10.5V16.5" />
  </svg>
);

export const SpinnerIcon = (props: IconProps) => (
  <svg {...icon(props)}>
    <path d="M12 3A9 9 0 1 0 21 12" />
  </svg>
);
